-- V5: streak (accumulator) predictions.
-- T-SQL "IF NOT EXISTS (sys.objects ...) CREATE TABLE" -> Postgres "CREATE TABLE IF NOT EXISTS".
-- BIGINT IDENTITY(1,1) -> bigint generated by default as identity; GETDATE() -> now().
CREATE TABLE IF NOT EXISTS streak_predictions (
    id bigint generated by default as identity primary key,
    spectator_id bigint NOT NULL,
    tournament_id bigint NOT NULL,
    wager_amount int NOT NULL,
    total_odds numeric(10,2) NOT NULL,
    status varchar(20) NOT NULL DEFAULT 'PENDING',
    reward_points int DEFAULT 0,
    created_at timestamp(6) DEFAULT now(),
    evaluated_at timestamp(6),
    FOREIGN KEY (spectator_id) REFERENCES users(id),
    FOREIGN KEY (tournament_id) REFERENCES tournaments(id)
);

CREATE TABLE IF NOT EXISTS streak_prediction_legs (
    id bigint generated by default as identity primary key,
    streak_prediction_id bigint NOT NULL,
    race_id bigint NOT NULL,
    predicted_winner_id bigint NOT NULL,
    locked_odds numeric(10,2) NOT NULL,
    status varchar(20) NOT NULL DEFAULT 'PENDING',
    FOREIGN KEY (streak_prediction_id) REFERENCES streak_predictions(id) ON DELETE CASCADE,
    FOREIGN KEY (race_id) REFERENCES races(id),
    FOREIGN KEY (predicted_winner_id) REFERENCES race_participants(id)
);
